"""Italiano — fede e pratica (faith_001 … faith_070)."""

T = {
"faith_001": ("Quanti pilastri ha l'Islam?", ["5", "4", "6", "7"], "L'hadith di Jibril e l'hadith riportato da Ibn 'Umar elencano i cinque pilastri dell'Islam."),
"faith_002": ("Come si chiama la dichiarazione di fede nell'Islam?", ["La Shahada", "La Salat", "La Zakat", "Lo Hajj"], "La Shahada, la testimonianza di fede, è il primo pilastro dell'Islam."),
"faith_003": ("Quante volte al giorno si compie la preghiera obbligatoria nell'Islam?", ["5", "3", "4", "7"], "Le cinque preghiere quotidiane obbligatorie sono un pilastro fondamentale dell'Islam."),
"faith_004": ("Come si chiama l'elemosina obbligatoria nell'Islam?", ["Zakat", "Sadaqa", "Waqf", "Kaffara"], "La zakat è l'elemosina obbligatoria, uno dei cinque pilastri dell'Islam."),
"faith_005": ("Come si chiama il mese di digiuno obbligatorio nell'Islam?", ["Ramadan", "Shawwal", "Rajab", "Muharram"], "Il Corano ordina il digiuno durante il mese di Ramadan."),
"faith_006": ("Come si chiama il pellegrinaggio alla Mecca, obbligatorio una volta nella vita per chi ne ha la possibilità?", ["Hajj", "'Umra", "I'tikaf", "Tawaf"], "Il Corano rende obbligatorio lo Hajj, almeno una volta nella vita, per chiunque sia in grado di compierlo."),
"faith_007": ("Verso quale direzione si rivolgono i musulmani per la preghiera?", ["La Ka'ba, alla Mecca", "Gerusalemme", "Medina", "L'Est"], "Il Corano ha stabilito la Ka'ba come direzione della preghiera (qibla)."),
"faith_008": ("Secondo un noto hadith, quanti sono gli articoli di fede (pilastri dell'Iman) comunemente insegnati?", ["6", "4", "5", "7"], "L'hadith di Jibril elenca sei articoli di fede: Allah, gli angeli, i libri, i messaggeri, l'Ultimo Giorno e il decreto divino."),
"faith_009": ("Come si chiama la purificazione con l'acqua che un musulmano compie prima di ogni preghiera?", ["Wudu (abluzione)", "Tayammum", "Ghusl", "Siwak"], "«Quando vi alzate per la preghiera, lavate i vostri volti e le vostre mani…»: questo è il wudu."),
"faith_010": ("Secondo il Corano, che cosa fanno i «nobili scribi» (kiraman katibin)?", ["Registrano le azioni delle persone", "Portano il Trono", "Custodiscono il Paradiso", "Portano la pioggia"], "«Su di voi vi sono custodi, nobili scribi»: gli angeli registrano ogni azione."),
"faith_011": ("Quanti bei nomi di Allah riporta la tradizione autentica?", ["99", "50", "100", "114"], "Un hadith autentico riportato da al-Bukhari e Muslim menziona novantanove nomi: cento meno uno."),
"faith_012": ("Che cosa significa il nome di Allah «Ar-Rahman»?", ["Il Misericordioso", "Il Creatore", "Il Re", "L'Onnisciente"], "Ar-Rahman, il Misericordioso: la Sua misericordia abbraccia ogni cosa."),
"faith_013": ("In Al-Fatiha, Allah è chiamato «Padrone» di quale giorno?", ["Il Giorno del Giudizio", "Il venerdì", "Il primo giorno", "Il giorno di 'Arafa"], "«Padrone del Giorno del Giudizio»: il giorno in cui ognuno incontra le proprie azioni."),
"faith_014": ("In quale giorno della settimana il Corano chiama i credenti alla preghiera comunitaria?", ["Venerdì", "Lunedì", "Sabato", "Domenica"], "«Quando si chiama alla preghiera del venerdì, accorrete al ricordo di Allah.»"),
"faith_015": ("Secondo il Corano, chi garantisce la preservazione del Corano da ogni alterazione?", ["Allah stesso", "Solo gli angeli", "Gli studiosi", "I re"], "«In verità, abbiamo fatto scendere il Ricordo, e in verità ne siamo i Custodi.»"),
"faith_016": ("Che cosa dichiara il Corano sull'ingresso nella religione?", ["Non c'è costrizione nella religione", "Avviene per giuramento", "Richiede un testimone", "Avviene alla maggiore età"], "«Non c'è costrizione nella religione: la retta via si distingue dall'errore.»"),
"faith_017": ("Qual è il saluto dei musulmani, un augurio di pace?", ["As-salamu 'alaykum", "Marhaban", "Sabah al-khayr", "Ahlan wa sahlan"], "«As-salamu 'alaykum»: la pace sia su di voi, a cui si risponde «wa 'alaykum as-salam»."),
"faith_018": ("Come si chiama la fede nell'unicità di Allah, il cuore dell'Islam?", ["Tawhid", "Tafsir", "Tajwid", "Tarawih"], "Il tawhid, affermare che Allah è Uno, senza associati, è il fondamento di tutta la fede."),
"faith_019": ("Quale Libro Allah rivelò al profeta Musa?", ["La Tawrat (Torah)", "L'Injil (Vangelo)", "Lo Zabur (Salmi)", "Il Corano"], "«Abbiamo fatto scendere la Tawrat, in cui vi era guida e luce» (5:44)."),
"faith_020": ("Quale Libro Allah diede al profeta 'Isa?", ["L'Injil (Vangelo)", "La Tawrat", "Lo Zabur", "I Fogli di Ibrahim"], "«Gli demmo l'Injil, in cui vi era guida e luce» (5:46)."),
"faith_021": ("Secondo il Corano, che cosa bisogna fare quando si viene salutati?", ["Rispondere con un saluto migliore, o ricambiarlo", "Restare in silenzio", "Abbassare lo sguardo", "Rispondere solo agli amici"], "«Quando vi si rivolge un saluto, salutate con uno migliore, o ricambiatelo» (4:86)."),
"faith_022": ("La sura Al-A'la menziona «i Fogli» (suhuf) di quali due profeti?", ["Ibrahim e Musa", "Nuh e Hud", "Dawud e Sulayman", "Zakariyya e Yahya"], "«Questo è nei Fogli antichi, i Fogli di Ibrahim e Musa» (87:18-19)."),
"faith_023": ("Qual è il nome dell'angelo custode dell'Inferno, menzionato nel Corano?", ["Malik", "Ridwan", "Mika'il", "Israfil"], "La gente dell'Inferno griderà: «O Malik, che il tuo Signore ci finisca!» (43:77)."),
"faith_024": ("Secondo la sura Al-Haqqa, quanti angeli porteranno il Trono di Allah nel Giorno della Resurrezione?", ["Otto", "Quattro", "Dodici", "Uno"], "«E in quel Giorno, otto porteranno il Trono del tuo Signore sopra di loro» (69:17)."),
"faith_025": ("Secondo il Corano, chi è incaricato di prendere le anime alla morte?", ["L'angelo della morte", "Jibril", "Il profeta", "I jinn"], "«Di': l'angelo della morte, incaricato di voi, prenderà le vostre anime» (32:11)."),
"faith_026": ("Da che cosa furono creati gli angeli, secondo un hadith in Sahih Muslim?", ["Dalla luce", "Dal fuoco", "Dall'argilla", "Dall'acqua"], "«Gli angeli furono creati dalla luce, i jinn da un fuoco senza fumo, e Adam da ciò che vi è stato descritto.»"),
"faith_027": ("Da che cosa furono creati i jinn, secondo il Corano?", ["Da un fuoco senza fumo", "Dalla luce", "Dall'argilla", "Dal vento"], "«E creò i jinn da una fiamma di fuoco senza fumo» (55:15)."),
"faith_028": ("Chi il Corano nomina come nemico dichiarato degli esseri umani?", ["Satana (ash-Shaytan)", "Gli angeli", "Gli animali", "La notte"], "«In verità, Satana è un nemico per voi; prendetelo dunque come nemico» (35:6)."),
"faith_029": ("Quanti profeti sono chiamati «Ulu al-'Azm» (quelli dalla ferma risoluzione)?", ["Cinque: Nuh, Ibrahim, Musa, 'Isa e Muhammad ﷺ", "Tre", "Dieci", "Venticinque"], "«Sii paziente come furono pazienti i messaggeri dalla ferma risoluzione» (46:35); la sura Ash-Shura (42:13) nomina questi cinque insieme."),
"faith_030": ("Che cosa sarà soffiato per annunciare la Resurrezione, secondo il Corano?", ["La Tromba (as-Sur)", "Un corno di ariete", "Un flauto", "Una campana"], "«Si soffierà nella Tromba, e chiunque sia nei cieli e sulla terra cadrà morto… poi vi si soffierà di nuovo» (39:68)."),
"faith_031": ("Come chiama il Corano ciò che peserà le azioni nel Giorno della Resurrezione?", ["Le bilance (al-Mawazin)", "Il registro", "Il ponte", "La tromba"], "«Disporremo le bilance giuste nel Giorno della Resurrezione; nessuna anima subirà torto alcuno» (21:47)."),
"faith_032": ("Quale nome dà il Corano al livello più alto del Paradiso, promesso a chi crede e fa il bene?", ["Al-Firdaws", "Al-Kawthar", "As-Sirat", "Al-A'raf"], "«Coloro che credono e compiono opere buone avranno come dimora i Giardini di Firdaws» (18:107)."),
"faith_033": ("Qual è il nome più comune dell'Inferno nel Corano?", ["Jahannam", "Firdaws", "Kawthar", "Tasnim"], "Il Corano chiama l'Inferno «Jahannam» decine di volte, ad esempio: «Sarete radunati in Jahannam» (3:12)."),
"faith_034": ("Quale pilastro della fede afferma il versetto «Abbiamo creato ogni cosa con misura»?", ["La fede nel decreto divino (al-qadar)", "La fede negli angeli", "La fede nei Libri", "La fede nei messaggeri"], "«Abbiamo creato ogni cosa secondo una misura (qadar)» (54:49): nulla avviene al di fuori della conoscenza e della volontà di Allah."),
"faith_035": ("Quale peccato Allah dichiara di non perdonare a chi muore senza pentirsene?", ["Lo shirk (associare partner ad Allah)", "La menzogna", "L'avarizia", "La collera"], "«Allah non perdona che Gli si associno partner, e perdona ciò che è meno di questo a chi vuole» (4:48)."),
"faith_036": ("Secondo il Corano, chi ama Allah tra coloro che hanno peccato?", ["Coloro che si pentono", "Coloro che nascondono i loro peccati", "Coloro che disperano", "Coloro che incolpano gli altri"], "«In verità, Allah ama coloro che si pentono e ama coloro che si purificano» (2:222)."),
"faith_037": ("Secondo la sura Nuh, che cosa porta a un popolo la richiesta di perdono (istighfar)?", ["Pioggia abbondante e benedizioni", "Nulla", "Una siccità", "Un lungo sonno"], "«Chiedete perdono al vostro Signore; in verità, Egli è Perdonatore. Vi invierà dal cielo pioggia abbondante» (71:10-11)."),
"faith_038": ("Che cosa promette il Corano a chi ripone la sua fiducia in Allah (tawakkul)?", ["Allah gli basta", "Diventerà ricco", "Non sarà mai malato", "Non dovrà più lavorare"], "«E chi confida in Allah, Egli gli basta» (65:3)."),
"faith_039": ("Che cosa dice Allah della supplica (du'a) nella sura Ghafir?", ["«InvocateMi, vi risponderò»", "«Invocate solo di notte»", "«Invocate gli angeli»", "«Il du'a è solo per i profeti»"], "«Il vostro Signore dice: invocateMi, vi risponderò» (40:60)."),
"faith_040": ("Grazie a che cosa, secondo il Corano, i cuori trovano pace?", ["Al ricordo di Allah (dhikr)", "Al denaro", "Al sonno", "Ai viaggi"], "«Non è forse con il ricordo di Allah che i cuori trovano pace?» (13:28)."),
"faith_041": ("Qual è la prima preghiera obbligatoria della giornata?", ["Al-Fajr (alba)", "Adh-Dhuhr (mezzogiorno)", "Al-'Asr (pomeriggio)", "Al-'Isha' (notte)"], "Le cinque preghiere sono, in ordine: Fajr, Dhuhr, 'Asr, Maghrib e 'Isha'."),
"faith_042": ("Quante rak'a ha la preghiera obbligatoria del Fajr?", ["Due", "Tre", "Quattro", "Una"], "Il Fajr ha due rak'a; il Maghrib tre; Dhuhr, 'Asr e 'Isha' quattro ciascuna."),
"faith_043": ("Quale preghiera obbligatoria ha tre rak'a?", ["Al-Maghrib", "Al-Fajr", "Adh-Dhuhr", "Al-'Isha'"], "Il Maghrib, subito dopo il tramonto, è l'unica preghiera obbligatoria con tre rak'a."),
"faith_044": ("Come si chiama la chiamata alla preghiera fatta dalla moschea?", ["L'adhan", "La khutba", "Il tasbih", "La talbiya"], "L'adhan è lanciato dal muezzin (mu'adhdhin) prima di ciascuna delle cinque preghiere."),
"faith_045": ("Secondo il versetto dell'abluzione, fino a dove vanno lavate le braccia?", ["Fino ai gomiti", "Fino ai polsi", "Fino alle spalle", "Solo le mani"], "«Lavate i vostri volti e le vostre mani fino ai gomiti, passate le mani sul capo e lavate i piedi fino alle caviglie» (5:6)."),
"faith_046": ("Che cosa permette il Corano quando non si trova acqua per purificarsi prima della preghiera?", ["Il tayammum con terra pulita", "Pregare senza purificazione", "Rimandare la preghiera al giorno dopo", "Lavarsi con sabbia bagnata"], "«Se non trovate acqua, cercate terra pulita e passatevi il volto e le mani» (5:6)."),
"faith_047": ("Come si chiama il sermone pronunciato dall'imam prima della preghiera del venerdì?", ["La khutba", "L'adhan", "L'iqama", "Il takbir"], "La khutba del venerdì è pronunciata in due parti dal minbar, prima della preghiera."),
"faith_048": ("Quale quota dei risparmi conservati per un anno intero versa un musulmano come zakat?", ["2,5%", "10%", "25%", "1%"], "La zakat sul denaro risparmiato è un quarto di un decimo, il 2,5%, una volta superata la soglia (nisab) per un anno lunare."),
"faith_049": ("Quale elemosina particolare è dovuta alla fine del Ramadan, prima della preghiera dell'Eid?", ["La zakat al-fitr", "La zakat sull'oro", "Il khums", "La kaffara"], "Il Profeta ﷺ rese obbligatoria la zakat al-fitr, un sa' di datteri o d'orzo, per ogni musulmano, giovane o anziano."),
"faith_050": ("Secondo il Corano, da quando a quando dura il digiuno quotidiano del Ramadan?", ["Dall'alba fino alla notte", "Da mezzogiorno alla sera", "Dall'alba a mezzogiorno", "Tutto il giorno e tutta la notte"], "«Mangiate e bevete finché il filo bianco dell'alba si distingua dal filo nero, poi completate il digiuno fino alla notte» (2:187)."),
"faith_051": ("Come si chiama il pasto consumato prima dell'alba da chi sta per digiunare?", ["Il suhur", "L'iftar", "La walima", "L'aqiqa"], "Il Profeta ﷺ disse: «Consumate il suhur, perché nel suhur c'è benedizione.»"),
"faith_052": ("Come si chiama il pasto che rompe il digiuno al tramonto?", ["L'iftar", "Il suhur", "Il tarawih", "Il tahajjud"], "L'iftar rompe il digiuno non appena tramonta il sole, all'ora della preghiera del Maghrib."),
"faith_053": ("Quante feste (Eid) ha l'Islam nell'anno?", ["Due: Eid al-Fitr e Eid al-Adha", "Solo una", "Quattro", "Dodici"], "L'Eid al-Fitr chiude il mese di Ramadan; l'Eid al-Adha cade il 10 Dhul-Hijja, durante il pellegrinaggio."),
"faith_054": ("Quale evento commemora l'Eid al-Adha?", ["Il sacrificio di Ibrahim, riscattato da un ariete", "La nascita del Profeta ﷺ", "La battaglia di Badr", "La rivelazione del Corano"], "Pronto a sacrificare suo figlio, Ibrahim lo vide riscattato: «Lo riscattammo con un grande sacrificio» (37:107)."),
"faith_055": ("In quale mese del calendario islamico si svolge il pellegrinaggio (hajj)?", ["Dhul-Hijja", "Ramadan", "Muharram", "Rajab"], "Lo hajj si svolge dall'8 al 13 Dhul-Hijja, dodicesimo e ultimo mese dell'anno lunare."),
"faith_056": ("In quale giorno di Dhul-Hijja i pellegrini sostano sulla piana di 'Arafat?", ["Il 9", "Il 1°", "Il 10", "Il 27"], "La sosta ad 'Arafat il 9 Dhul-Hijja è il pilastro centrale dello hajj; l'Eid al-Adha segue il giorno dopo."),
"faith_057": ("Quanti giri intorno alla Ka'ba compongono un tawaf?", ["Sette", "Tre", "Cinque", "Dieci"], "Il tawaf è di sette giri intorno alla Ka'ba, in senso antiorario, a partire dalla Pietra Nera."),
"faith_058": ("Quanti percorsi tra As-Safa e Al-Marwa compongono il sa'y?", ["Sette", "Due", "Quattro", "Dodici"], "Il sa'y ricorda la ricerca dell'acqua di Hajar per Isma'il: sette percorsi, da Safa a Marwa e ritorno, ogni direzione contata."),
"faith_059": ("Come si chiama lo stato di consacrazione in cui entra il pellegrino, con i suoi due teli bianchi?", ["Ihram", "Tawaf", "Wuquf", "Talbiya"], "In ihram, gli uomini indossano due teli non cuciti e il pellegrino si astiene da profumi, caccia e litigi."),
"faith_060": ("Con quali parole inizia la talbiya, ripetuta dai pellegrini in cammino verso la Mecca?", ["«Labbayka Allahumma labbayk» (Eccomi, o Allah, eccomi)", "«Allahu akbar»", "«Subhana Allah»", "«Al-hamdu li-Llah»"], "La talbiya del Profeta ﷺ era: «Labbayka Allahumma labbayk, labbayka la sharika laka labbayk…»"),
"faith_061": ("Che cosa fanno i pellegrini a Mina quando lanciano sassolini contro tre pilastri?", ["La lapidazione delle jamarat", "Il tawaf", "Il sa'y", "La sosta ad 'Arafat"], "Il ramy al-jamarat ricorda Ibrahim che scacciò Satana con le pietre; si compie a Mina nei giorni dell'Eid."),
"faith_062": ("Dove si trova la Pietra Nera (al-Hajar al-Aswad)?", ["In un angolo della Ka'ba", "Sul monte 'Arafat", "A Medina", "In cima al monte Hira'"], "Incastonata nell'angolo orientale della Ka'ba, segna il punto di partenza di ogni giro del tawaf."),
"faith_063": ("Come si chiama il grande drappo nero che ricopre la Ka'ba?", ["La kiswa", "L'hijab", "Il minbar", "Il mihrab"], "La kiswa, ricamata con versetti in filo d'oro, viene sostituita ogni anno durante il pellegrinaggio."),
"faith_064": ("Come si chiama il pellegrinaggio «minore» alla Mecca, che si può compiere in qualsiasi periodo dell'anno?", ["La 'umra", "Lo hajj", "La hijra", "La ziyara"], "La 'umra consiste in ihram, tawaf e sa'y; a differenza dello hajj, non è legata a un mese specifico."),
"faith_065": ("Che cosa significa il nome di Allah «Al-Khaliq»?", ["Il Creatore", "Il Perdonatore", "Il Provvidente", "Il Re"], "«Egli è Allah, il Creatore (al-Khaliq), l'Originatore, il Modellatore» (59:24)."),
"faith_066": ("Che cosa significa il nome di Allah «Al-Ghafur»?", ["Il Perdonatore", "Il Creatore", "L'Onnipotente", "Il Generoso"], "«Non disperate della misericordia di Allah… Egli è il Perdonatore (al-Ghafur), il Misericordioso» (39:53)."),
"faith_067": ("Che cosa significano i due nomi di Allah «As-Sami'» e «Al-Basir»?", ["Colui che tutto ode e Colui che tutto vede", "Il Re e il Giudice", "Il Creatore e il Provvidente", "Il Primo e l'Ultimo"], "Il versetto del Viaggio notturno termina: «Egli è Colui che ode (as-Sami'), Colui che vede (al-Basir)» (17:1)."),
"faith_068": ("Che cosa significa «As-Samad», un nome di Allah nella sura Al-Ikhlas?", ["Colui da cui tutto dipende e che non dipende da nessuno", "Colui che perdona", "Colui che ode", "Colui che crea"], "«Allahu as-Samad» (112:2): il Padrone assoluto a cui tutte le creature si rivolgono per i loro bisogni."),
"faith_069": ("Quali due nomi di Allah aprono il Versetto del Trono, subito dopo «Allah, non c'è dio all'infuori di Lui»?", ["Al-Hayy e Al-Qayyum (il Vivente, Colui che sussiste da Sé)", "Ar-Rahman e Ar-Rahim", "Al-Malik e Al-Quddus", "Al-'Aziz e Al-Hakim"], "«Allah! Non c'è dio all'infuori di Lui, il Vivente, Colui che sussiste da Sé» (2:255)."),
"faith_070": ("Che cosa significa il nome di Allah «Ar-Razzaq»?", ["Il grande Provvidente", "Il Perdonatore", "Il Giusto", "Il Benevolo"], "«In verità, Allah è il Provvidente (ar-Razzaq), il Detentore della forza, il Saldo» (51:58)."),
}
